export type IconName = keyof typeof PATHS

export function Icon({ name, size = 18 }: { name: IconName; size?: number }) {
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} fill="currentColor" aria-hidden="true" focusable="false">
      <path d={PATHS[name]} />
    </svg>
  )
}

/** The Photon ring: the company's mark, in its yellow. Decorative: the product's name always sits beside it. */
export function PhotonMark({ height = 20 }: { height?: number }) {
  return (
    <svg viewBox="0 0 64 40" height={height} width={(height * 64) / 40} aria-hidden="true" focusable="false">
      <ellipse rx="29" ry="9.5" transform="translate(32 20) rotate(-18)" fill="none" strokeWidth="5.5" style={{ stroke: 'var(--brand)' }} />
    </svg>
  )
}
